package main

import (
	"database/sql"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
}

// searchHandler allows searching products by various criteria
func searchHandler(w http.ResponseWriter, r *http.Request) {
	category := r.URL.Query().Get("category")
	minPrice := r.URL.Query().Get("min_price")
	maxPrice := r.URL.Query().Get("max_price")
	sortBy := r.URL.Query().Get("sort")

	// Build dynamic query
	var conditions []string
	if category != "" {
		conditions = append(conditions, fmt.Sprintf("category = '%s'", category))
	}
	if minPrice != "" {
		conditions = append(conditions, fmt.Sprintf("price >= %s", minPrice))
	}
	if maxPrice != "" {
		conditions = append(conditions, fmt.Sprintf("price <= %s", maxPrice))
	}

	query := "SELECT id, name, price, category, description FROM products"
	if len(conditions) > 0 {
		query += " WHERE " + strings.Join(conditions, " AND ")
	}

	// Sort validation - only allow known columns
	allowedSorts := map[string]bool{"price": true, "name": true, "category": true}
	if sortBy != "" && allowedSorts[sortBy] {
		query += " ORDER BY " + sortBy
	}

	query += " LIMIT 50"

	rows, err := db.Query(query)
	if err != nil {
		log.Printf("Query error: %v", err)
		http.Error(w, "Internal server error", http.StatusInternalServerError)
		return
	}
	defer rows.Close()

	w.Header().Set("Content-Type", "application/json")
	w.Write([]byte("[\n"))
	first := true
	for rows.Next() {
		var id int
		var name, category, description string
		var price float64
		if err := rows.Scan(&id, &name, &price, &category, &description); err != nil {
			continue
		}
		if !first {
			w.Write([]byte(",\n"))
		}
		first = false
		w.Write([]byte(fmt.Sprintf(`  {"id":%d,"name":"%s","price":%.2f,"category":"%s","description":"%s"}`,
			id, name, price, category, description)))
	}
	w.Write([]byte("\n]"))
}

// healthHandler for ALB health checks
func healthHandler(w http.ResponseWriter, r *http.Request) {
	if err := db.Ping(); err != nil {
		http.Error(w, "unhealthy", http.StatusServiceUnavailable)
		return
	}
	w.Write([]byte("ok"))
}

// adminHandler for internal metrics
func adminHandler(w http.ResponseWriter, r *http.Request) {
	apiKey := r.Header.Get("X-Admin-Key")
	if apiKey != os.Getenv("ADMIN_API_KEY") {
		http.Error(w, "forbidden", http.StatusForbidden)
		return
	}
	stats := db.Stats()
	w.Write([]byte(fmt.Sprintf(`{"open_connections":%d,"in_use":%d}`, stats.OpenConnections, stats.InUse)))
}

func main() {
	http.HandleFunc("/api/search", searchHandler)
	http.HandleFunc("/health", healthHandler)
	http.HandleFunc("/admin/stats", adminHandler)
	log.Printf("Starting server on :8080")
	log.Fatal(http.ListenAndServe(":8080", nil))
}
